  "highland-park":    { name:"Highland Park, TN",      desc:"Highland Park is one of Chattanooga's most vibrant historic neighborhoods with tree-lined streets, revitalized bungalows, and neighbors who care about their blocks. Scoopy Doo runs regular Chattanooga routes through Highland Park, providing reliable urban yard cleanup.", hoods:["Highland Park proper","McCallie Avenue corridor","Third Street area","Dodds Avenue vicinity","Glass Street area","Orchard Knob nearby"], faqs:[["Do you service small urban yards in Highland Park?","Yes. We service yards of all sizes including the smaller urban lots typical in Highland Park. Smaller yards often mean waste is more concentrated and more important to keep clean consistently."],["How often should I have service?","For most Highland Park households with one or two dogs, weekly service is the best choice. Smaller yards fill up quickly and weekly pickup keeps odor and accumulation under control."],["Is Highland Park within the Chattanooga service area?","Yes. Highland Park is one of our established Chattanooga neighborhoods. We run regular city routes and Highland Park is well within our coverage area."]] },
  "flintstone":       { name:"Flintstone, GA",         desc:"Flintstone is a Walker County community in the hills of North Georgia with a mix of rural homesteads and established residential neighborhoods. Scoopy Doo serves Flintstone as part of our North Georgia coverage with no extra Walker County fees.", hoods:["Flintstone proper","US-27 corridor","Walker County residential","Lookout Valley vicinity","Cloud Springs Road area"], faqs:[["Do you service Flintstone, GA?","Yes. Flintstone is within our North Georgia service coverage. We do not charge extra fees for Walker County locations. Pricing is based on yard size and number of dogs."],["Do you sanitize your equipment between yards?","Yes, always. We sanitize all tools and footwear between every single yard to prevent the spread of bacteria and parasites."],["Can you handle larger rural properties?","Yes. We service a range of property sizes including larger rural lots and use a grid-pattern approach to make sure nothing is missed."]] },
